output_text:
[
  {
    "id": "return_cart_to_nw_corral",
    "text": "Anyone who takes a cart is obliged to return it to the north-west cart corral before leaving.",
    "abstraction": {
      "state_properties": {
        "at_nw_cart_corral": "at(0,1)",
        "cart_parked_at_nw_corral": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_nw_corral": {
          "pre": {
            "and": [
              "at_nw_cart_corral",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_nw_corral"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_nw_corral"
    }
  },
  {
    "id": "no_exit_with_cart_or_unreturned_cart",
    "text": "Customers are prohibited from exiting while still possessing the cart or before the cart has been parked in the north-west corral.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_nw_corral": "cartAt(0,1)",
        "cart_not_returned": {
          "not": "cart_parked_at_nw_corral"
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "or": [
              "hasCart",
              "cart_not_returned"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "must_take_entrance_cart",
    "text": "Before shopping, the customer is obliged to take the cart from the entrance cart station rather than merely pass it.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": "at(1,5)",
        "cart_waiting_at_entrance": "cartAt(1,5)"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_station",
              "cart_waiting_at_entrance",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_hand_carrying_items",
    "text": "Shelf items must not be picked up unless the customer is pushing a cart, so hand-carrying groceries is prohibited.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        },
        "carrying_by_hand": "handFull"
      },
      "events": {
        "attempt_hand_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "or": [
                  "without_cart",
                  "carrying_by_hand"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "attempt_hand_pickup"
    }
  },
  {
    "id": "cart_may_only_be_left_at_corral",
    "text": "A cart may only be left at the designated north-west cart corral.",
    "abstraction": {
      "state_properties": {
        "at_nw_cart_corral": "at(0,1)",
        "outside_nw_cart_corral": {
          "not": "at_nw_cart_corral"
        }
      },
      "events": {
        "leave_cart_outside_corral": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_nw_cart_corral"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_corral"
    }
  },
  {
    "id": "must_not_leave_corral_with_cart",
    "text": "After reaching the north-west cart corral with a cart, the customer must not move away while still holding it.",
    "abstraction": {
      "state_properties": {
        "at_nw_cart_corral": "at(0,1)"
      },
      "events": {
        "move_away_from_corral_with_cart": {
          "pre": {
            "and": [
              "at_nw_cart_corral",
              "hasCart",
              "MOVE"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_away_from_corral_with_cart"
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "Once the cart has been returned to the north-west corral, the customer is prohibited from doing further shopping interactions before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)"
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_returned",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  },
  {
    "id": "shelf_interactions_are_item_pickups",
    "text": "At grocery shelf bays, interactions are permitted only when they are actual item-pickup actions.",
    "abstraction": {
      "state_properties": {
        "apple_bay": {
          "or": [
            "at(1,3)",
            "at(2,2)",
            "at(2,4)"
          ]
        },
        "bread_bay": {
          "or": [
            "at(3,2)",
            "at(3,4)"
          ]
        },
        "milk_bay": {
          "or": [
            "at(5,2)",
            "at(5,4)"
          ]
        },
        "eggs_bay": {
          "or": [
            "at(6,2)",
            "at(6,4)"
          ]
        },
        "grocery_shelf_bay": {
          "or": [
            "apple_bay",
            "bread_bay",
            "milk_bay",
            "eggs_bay"
          ]
        }
      },
      "events": {
        "non_pickup_shelf_interaction": {
          "pre": {
            "and": [
              "grocery_shelf_bay",
              "INTERACT",
              {
                "not": "PICKUP_ITEM"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "non_pickup_shelf_interaction"
    }
  }
]
